def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    down_count = 0  # bar on bottom, stem above
    up_count = 0    # bar on top, stem below

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            cells = set()
            while stack:
                y, x = stack.pop()
                cells.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == 2 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            if len(cells) != 4:
                continue

            top = min(y for y, x in cells)
            bottom = max(y for y, x in cells)
            left = min(x for y, x in cells)
            right = max(x for y, x in cells)
            if bottom - top != 1 or right - left != 2:
                continue

            top_bar = {(top, x) for x in range(left, right + 1)}
            bottom_bar = {(bottom, x) for x in range(left, right + 1)}
            if cells == top_bar | {(top + 1, left + 1)}:
                up_count += 1
            elif cells == bottom_bar | {(bottom - 1, left + 1)}:
                down_count += 1

    out = [[0] * 6 for _ in range(3)]
    slots = [(0, 0), (2, 0), (0, 2), (2, 2)]

    for count, color, offset in ((down_count, 3, 0), (up_count, 1, 3)):
        for row, col in slots[:min(count, 4)]:
            out[row][offset + col] = color

    return out
